def compute(vars):
    numerator = vars["v1"]
    denominator = vars["v2"]

    if denominator == 0:
        return None

    ratio = numerator / denominator * 100

    return {
        "value": ratio,
        "trace": {
            "numerator": numerator,
            "denominator": denominator,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
